// Builds the static web preview served under a sub-path.
//   PET_WEB_BASE_PATH=/iSquared/preview/pet-show-and-tell/ npm run export:web
// Output: dist-web/web (static files) and dist-web/manifest.json.
import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { expoBaseUrlFromEnv } from './lib/base-path.cjs';
import { verifyWebExport } from './lib/verify-web-export.mjs';
import {
  EXPORT_GENERATOR,
  outputFileHashes,
  validateWebOutputLocation,
} from './lib/web-output-safety.mjs';

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outRoot = path.resolve(appRoot, 'dist-web');
const webDir = path.join(outRoot, 'web');
const stagingDir = path.join(outRoot, '.export-staging');

function git(...gitArgs) {
  const result = spawnSync('git', gitArgs, { cwd: appRoot, encoding: 'utf8' });
  return result.status === 0 ? result.stdout.trim() : '';
}

function removeStaging() {
  fs.rmSync(stagingDir, { recursive: true, force: true });
}

const basePath = expoBaseUrlFromEnv();
const envBase = basePath || '/';
validateWebOutputLocation(appRoot, outRoot);
fs.mkdirSync(outRoot, { recursive: true });
removeStaging();

console.log(`[export-web] base ${envBase} -> dist-web/web`);
const expoCli = path.join(appRoot, 'node_modules', 'expo', 'bin', 'cli');
const build = spawnSync(
  process.execPath,
  [expoCli, 'export', '--platform', 'web', '--output-dir', stagingDir, '--clear'],
  {
    cwd: appRoot,
    stdio: 'inherit',
    env: { ...process.env, PET_WEB_BASE_PATH: envBase },
  }
);
if (build.status !== 0) {
  removeStaging();
  throw new Error(`expo export failed with exit code ${build.status}`);
}

const { errors, files } = verifyWebExport({ dir: stagingDir, basePath });
if (errors.length > 0) {
  console.error('[export-web] verification failed:');
  for (const error of errors) {
    console.error(`  - ${error}`);
  }
  removeStaging();
  process.exit(1);
}

fs.rmSync(webDir, { recursive: true, force: true });
fs.renameSync(stagingDir, webDir);

const fileHashes = outputFileHashes(webDir);
const totalBytes = Object.keys(fileHashes).reduce(
  (sum, rel) => sum + fs.statSync(path.join(webDir, rel)).size,
  0
);
if (files.length !== Object.keys(fileHashes).length) {
  throw new Error('Verification file list does not match the manifest inventory.');
}

const manifest = {
  generator: EXPORT_GENERATOR,
  basePath: envBase,
  builtAt: new Date().toISOString(),
  gitCommit: git('rev-parse', 'HEAD') || null,
  gitDirty: git('status', '--porcelain', '--', '.') !== '',
  fileCount: Object.keys(fileHashes).length,
  totalBytes,
  indexHtmlSha256: crypto
    .createHash('sha256')
    .update(fs.readFileSync(path.join(webDir, 'index.html')))
    .digest('hex'),
  fileHashes,
};
fs.writeFileSync(path.join(outRoot, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(
  `[export-web] OK: ${manifest.fileCount} files, ${(totalBytes / 1048576).toFixed(1)} MiB, verification passed`
);

// Normalizes PET_WEB_BASE_PATH for Expo's experiments.baseUrl.
// Empty string means the site root. A sub-path is "/like/this" with no trailing slash.

function normalizeBasePath(value) {
  const raw = String(value ?? '').trim();
  if (!raw || raw === '/') {
    return '';
  }
  if (/^[a-z][a-z0-9+.-]*:/i.test(raw) || raw.startsWith('//')) {
    throw new Error(`Base path must be a path, not a URL: ${raw}`);
  }
  if (/[?#\s\\]/.test(raw)) {
    throw new Error(`Base path must not contain whitespace, backslashes, "?" or "#": ${raw}`);
  }
  const segments = raw.split('/').filter(Boolean);
  if (segments.some((segment) => segment === '.' || segment === '..')) {
    throw new Error(`Base path must not contain "." or ".." segments: ${raw}`);
  }
  if (segments.length === 0) {
    return '';
  }
  return `/${segments.join('/')}`;
}

function expoBaseUrlFromEnv(env = process.env) {
  return normalizeBasePath(env.PET_WEB_BASE_PATH);
}

module.exports = { expoBaseUrlFromEnv, normalizeBasePath };

import fs from 'node:fs';
import path from 'node:path';

const TEXT_EXTENSIONS = new Set([
  '.html',
  '.js',
  '.mjs',
  '.css',
  '.json',
  '.svg',
  '.txt',
  '.webmanifest',
]);
const SOURCE_MAP = /\/\/[#@]\s*sourceMappingURL=/;
const LOCAL_HOST = /(?:https?|wss?):\/\/(?:localhost|127\.0\.0\.1|\[::1\])/i;
const NET_URL = /(?:https?|wss?):\/\/[^\s"'`<>)\\]+/gi;
const ESCAPED_NET_URL = /(?:https?|wss?):\\\/\\\/[^\s"'`)\\]+/gi;
const BUNDLE_MARKERS = ['wa-sqlite', 'ExpoSQLite', 'ExponentFileSystem'];

// Hosts that production dependencies leave in warning text, XML namespace
// identifiers, or unused fallbacks. A URL on one of these hosts is still a
// failure when it sits in a request position. The browser smoke test has to
// show that none of them are requested. Do not add an app-owned host.
export const INERT_HOSTS = [
  'www.w3.org', // SVG and MathML XML namespace identifiers
  'react.dev', // React minified error-decoder text
  'necolas.github.io', // HTML comment from Expo's static renderer
  'docs.expo.dev', // expo-router warning text
  'docs.swmansion.com', // reanimated and worklets warning text
  'github.com', // dependency warning and issue links
  'dev.to', // iOS motion-permission note inside a dependency
  'expo.dev', // expo-asset default server when a local URI is missing
  'classic-assets.eascdn.net', // expo-asset URL used only inside Expo Go
  'hostname', // template base in a URL helper, not a network host
  'e', // dummy base passed to new URL(value, "https://e")
];

const INERT_HOST_SET = new Set(INERT_HOSTS);

function* walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) {
      throw new Error(`Output contains a symlink: ${full}`);
    }
    if (entry.isDirectory()) {
      yield* walk(full);
    } else if (entry.isFile()) {
      yield full;
    } else {
      throw new Error(`Unexpected output entry: ${full}`);
    }
  }
}

function unescapeUrl(value) {
  return value.replace(/\\\//g, '/').replace(/[),.;]+$/g, '');
}

function hostOf(raw) {
  const match = /^(?:https?|wss?):\/\/([^/?#\s:]+)/i.exec(unescapeUrl(raw));
  return match ? match[1].toLowerCase().replace(/\.$/, '') : null;
}

function isRequestPosition(text, index) {
  const before = text.slice(Math.max(0, index - 180), index);
  return /(?:\bfetch|\bimport|new\s+WebSocket|new\s+Worker|new\s+SharedWorker|new\s+EventSource|\bsendBeacon|\.open)\s*\(\s*(?:['"][A-Za-z*]+['"]\s*,\s*)?['"`]?\s*$/i.test(
    before
  );
}

function checkNetworkUrl(rel, text, raw, index, errors) {
  const url = unescapeUrl(raw);
  const host = hostOf(raw);
  if (isRequestPosition(text, index)) {
    errors.push(`${rel}: request to ${url}`);
    return;
  }
  if (!host || !INERT_HOST_SET.has(host)) {
    errors.push(`${rel}: off-origin URL ${url}`);
  }
}

function checkAsset(url, where, base, errors) {
  if (
    !url ||
    url.startsWith('data:') ||
    url.startsWith('blob:') ||
    url.startsWith('#') ||
    url.startsWith('mailto:') ||
    url.startsWith('javascript:')
  ) {
    return;
  }
  if (url.startsWith('//') || /^[a-z][a-z0-9+.-]*:/i.test(url)) {
    errors.push(`${where}: "${url}" is not a same-origin asset path`);
    return;
  }
  if (!url.startsWith('/')) {
    errors.push(`${where}: "${url}" is relative; expected an absolute path under the base`);
    return;
  }
  if (base && url !== base && !url.startsWith(`${base}/`)) {
    errors.push(`${where}: "${url}" is outside base ${base}/`);
  }
}

function looksLikeAssetPath(url) {
  return (
    url.includes('/_expo/') ||
    url.includes('/assets/') ||
    /\.(?:png|jpe?g|gif|webp|svg|ico|ttf|otf|woff2?|css|js|json)(?:$|\?)/i.test(url)
  );
}

export function verifyWebExport({ dir, basePath }) {
  const errors = [];
  const files = [];
  const indexPath = path.join(dir, 'index.html');
  const base = basePath && basePath !== '/' ? String(basePath).replace(/\/+$/, '') : '';

  if (!fs.existsSync(indexPath)) {
    return { errors: [`index.html not found in ${dir}`], files };
  }

  for (const file of walk(dir)) {
    const rel = path.relative(dir, file).split(path.sep).join('/');
    files.push(rel);
    if (path.basename(file).endsWith('.map')) {
      errors.push(`${rel}: sourcemap must not be shipped`);
    }
    if (!TEXT_EXTENSIONS.has(path.extname(file).toLowerCase())) {
      continue;
    }

    const text = fs.readFileSync(file, 'utf8');
    if (SOURCE_MAP.test(text)) {
      errors.push(`${rel}: contains a sourceMappingURL`);
    }
    if (LOCAL_HOST.test(text)) {
      errors.push(`${rel}: references a localhost URL`);
    }
    for (const marker of BUNDLE_MARKERS) {
      if (text.includes(marker)) {
        errors.push(`${rel}: bundles ${marker}`);
      }
    }

    for (const match of text.matchAll(NET_URL)) {
      checkNetworkUrl(rel, text, match[0], match.index ?? 0, errors);
    }
    for (const match of text.matchAll(ESCAPED_NET_URL)) {
      checkNetworkUrl(rel, text, match[0], match.index ?? 0, errors);
    }
    for (const match of text.matchAll(/(?:^|["'(=\s])(\/\/[a-z0-9.-]+\.[a-z]{2,}[^"'`\s<)]*)/gi)) {
      errors.push(`${rel}: protocol-relative URL ${match[1]}`);
    }

    if (rel.endsWith('.css') || rel.endsWith('.html')) {
      for (const match of text.matchAll(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi)) {
        checkAsset(match[2], rel, base, errors);
      }
    }
    if (rel.endsWith('.html')) {
      for (const match of text.matchAll(/\b(?:src|href)=["']([^"']+)["']/g)) {
        checkAsset(match[1], rel, base, errors);
      }
    }
    if (rel.endsWith('.js')) {
      for (const match of text.matchAll(/["'](\/[^"']+)["']/g)) {
        if (looksLikeAssetPath(match[1])) {
          checkAsset(match[1], rel, base, errors);
        }
      }
    }
  }

  return { errors, files };
}

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

export const EXPORT_GENERATOR = 'pet-show-and-tell/export-web';

const sha256 = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');

function entryExists(file) {
  try {
    fs.lstatSync(file);
    return true;
  } catch (error) {
    if (error.code === 'ENOENT') {
      return false;
    }
    throw error;
  }
}

export function outputFileHashes(dir) {
  const files = {};
  const visit = (current) => {
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      const full = path.join(current, entry.name);
      if (entry.isSymbolicLink()) {
        throw new Error(`Output contains a symlink: ${full}`);
      }
      if (entry.isDirectory()) {
        if (fs.readdirSync(full).length === 0) {
          throw new Error(`Output contains an empty directory: ${full}`);
        }
        visit(full);
        continue;
      }
      if (!entry.isFile()) {
        throw new Error(`Unexpected output entry: ${full}`);
      }
      files[path.relative(dir, full).split(path.sep).join('/')] = sha256(full);
    }
  };
  visit(dir);
  return files;
}

/** Replace only a previous export from this script. Leave every other folder alone. */
export function validateWebOutputLocation(appRoot, outRoot) {
  const relative = path.relative(appRoot, outRoot);
  if (
    !relative ||
    relative === '..' ||
    relative.startsWith(`..${path.sep}`) ||
    path.isAbsolute(relative)
  ) {
    throw new Error(`Output must be a subdirectory of ${appRoot}`);
  }

  let current = appRoot;
  for (const part of relative.split(path.sep)) {
    current = path.join(current, part);
    if (entryExists(current) && fs.lstatSync(current).isSymbolicLink()) {
      throw new Error(`Output cannot traverse a symlink: ${current}`);
    }
  }
  if (!entryExists(outRoot)) {
    return null;
  }

  const web = path.join(outRoot, 'web');
  const manifestPath = path.join(outRoot, 'manifest.json');
  for (const file of [web, manifestPath, path.join(outRoot, '.export-staging')]) {
    if (entryExists(file) && fs.lstatSync(file).isSymbolicLink()) {
      throw new Error(`Output cannot be a symlink: ${file}`);
    }
  }

  const unexpected = fs
    .readdirSync(outRoot)
    .filter((name) => name !== 'web' && name !== 'manifest.json' && name !== '.export-staging');
  if (unexpected.length > 0) {
    throw new Error(
      `Refusing to overwrite an output folder this exporter did not create. Unexpected entries: ${unexpected.join(', ')}`
    );
  }

  const webExists = fs.existsSync(web);
  const manifestExists = fs.existsSync(manifestPath);
  if (!webExists && !manifestExists) {
    return null;
  }
  if (!webExists || !manifestExists || !fs.statSync(web).isDirectory()) {
    throw new Error('Refusing to overwrite an output folder this exporter did not create.');
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  } catch {
    throw new Error('Refusing to overwrite an invalid export manifest.');
  }
  if (manifest.generator !== EXPORT_GENERATOR) {
    throw new Error('Refusing to overwrite an output folder this exporter did not create.');
  }

  const hashes = outputFileHashes(web);
  if (
    !hashes['index.html'] ||
    hashes['index.html'] !== manifest.indexHtmlSha256 ||
    Object.keys(hashes).length !== manifest.fileCount
  ) {
    throw new Error('Refusing to replace output changed since the previous web export.');
  }
  if (
    !manifest.fileHashes ||
    typeof manifest.fileHashes !== 'object' ||
    Array.isArray(manifest.fileHashes)
  ) {
    throw new Error('The previous web export has no file inventory.');
  }
  const changed = Object.entries(hashes).some(([name, hash]) => manifest.fileHashes[name] !== hash);
  if (Object.keys(manifest.fileHashes).length !== Object.keys(hashes).length || changed) {
    throw new Error('Refusing to replace output changed since the previous web export.');
  }
  return manifest;
}

// Browser check for the static preview. Run after export:web. Not part of npm test.
// Serves dist-web/web under the manifest base path, with no COOP/COEP headers.
import { createRequire } from 'node:module';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const playwrightCore = path.resolve(
  '<local>/mrdj-dev-suite-i2Workspace/temp/exact-upstream/node_modules/playwright-core'
);
const { chromium } = require(playwrightCore);

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const webDir = path.join(appRoot, 'dist-web', 'web');
const manifestPath = path.join(appRoot, 'dist-web', 'manifest.json');
const shotDir = path.join(appRoot, 'tmp', 'web-smoke');
const uploadPath = path.join(appRoot, 'assets', 'images', 'pets', 'Tippy.jpeg');

const PET_NAMES = ['Nora', 'Mia', 'Mrs Frizzle', 'Nala', "Lil' Mama", 'Louie', 'Tippy'];
const CAPTIONS = [
  'A cozy moment with Nora.',
  'A little moment with Mia.',
  'Meet Mrs Frizzle.',
  'Meet Nala.',
  "A moment with Lil' Mama.",
  'Happy wiggles and sunny smiles.',
  'A moment with Louie.',
  'Another moment with Louie.',
  'A moment with Tippy.',
];
const NEW_PET = 'Smoke Biscuit';
const NEW_CAPTION = 'Smoke biscuit chased a sunbeam.';

const MIME = {
  '.css': 'text/css; charset=utf-8',
  '.gif': 'image/gif',
  '.html': 'text/html; charset=utf-8',
  '.ico': 'image/x-icon',
  '.jpeg': 'image/jpeg',
  '.jpg': 'image/jpeg',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.ttf': 'font/ttf',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

function fail(message) {
  const error = new Error(message);
  error.smoke = true;
  throw error;
}

function startServer(basePath) {
  const base = basePath === '/' ? '' : basePath.replace(/\/+$/, '');
  const server = http.createServer((request, response) => {
    const url = new URL(request.url || '/', 'http://<loopback>');
    const pathname = decodeURIComponent(url.pathname);
    const inBase = base ? pathname === base || pathname.startsWith(`${base}/`) : true;
    if (!inBase) {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('outside the preview base path');
      return;
    }
    const rel = (base ? pathname.slice(base.length) : pathname) || '/';
    const filePath = path.normalize(path.join(webDir, rel === '/' ? 'index.html' : rel));
    if (filePath !== webDir && !filePath.startsWith(webDir + path.sep)) {
      response.writeHead(403).end();
      return;
    }
    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
      const type = MIME[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
      response.writeHead(200, {
        'Cache-Control': 'no-store',
        'Content-Type': type,
      });
      fs.createReadStream(filePath).pipe(response);
      return;
    }
    if (path.extname(rel)) {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end(`missing ${rel}`);
      return;
    }
    response.writeHead(200, {
      'Cache-Control': 'no-store',
      'Content-Type': 'text/html; charset=utf-8',
    });
    fs.createReadStream(path.join(webDir, 'index.html')).pipe(response);
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      resolve({
        server,
        origin: `http://<loopback>:${address.port}`,
        base,
      });
    });
  });
}

async function shot(page, name) {
  await page.screenshot({ path: path.join(shotDir, name) });
}

async function bodyText(page) {
  return page.locator('body').innerText();
}

async function waitForText(page, text) {
  const started = Date.now();
  while (Date.now() - started < 15000) {
    if ((await bodyText(page)).includes(text)) {
      return;
    }
    await page.waitForTimeout(100);
  }
  fail(`Timed out waiting for "${text}" at ${page.url()}`);
}

async function assertTextGone(page, text) {
  if ((await bodyText(page)).includes(text)) {
    fail(`"${text}" is still on screen at ${page.url()}`);
  }
}

async function scrollFeed(page) {
  const seen = new Set();
  for (let step = 0; step < 30; step += 1) {
    for (const line of (await bodyText(page)).split('\n')) {
      const trimmed = line.trim();
      if (trimmed) {
        seen.add(trimmed);
      }
    }
    const moved = await page.evaluate(() => {
      const candidates = [...document.querySelectorAll('div')].filter(
        (el) => el.scrollHeight > el.clientHeight + 40 && el.clientHeight > 180
      );
      candidates.sort((left, right) => right.clientHeight - left.clientHeight);
      const scroller = candidates[0];
      if (!scroller) {
        return false;
      }
      const before = scroller.scrollTop;
      scroller.scrollTop = before + Math.max(240, Math.floor(scroller.clientHeight * 0.75));
      return scroller.scrollTop !== before;
    });
    if (!moved && step > 2) {
      break;
    }
    await page.waitForTimeout(40);
  }
  return seen;
}

async function assertNoHorizontalOverflow(page, label) {
  const box = await page.evaluate(() => ({
    clientWidth: document.documentElement.clientWidth,
    scrollWidth: document.documentElement.scrollWidth,
  }));
  if (box.scrollWidth > box.clientWidth + 1) {
    fail(`${label}: horizontal overflow ${box.scrollWidth}px > ${box.clientWidth}px`);
  }
}

async function fillField(page, label, value) {
  const field = page.getByLabel(label);
  await field.click();
  await field.fill(value);
  const current = await field.inputValue();
  if (current !== value) {
    fail(`${label} kept "${current}" instead of "${value}"`);
  }
}

async function chooseUpload(page, buttonName) {
  const chooserPromise = page.waitForEvent('filechooser', { timeout: 8000 });
  await page.getByRole('button', { name: buttonName }).click();
  const chooser = await chooserPromise;
  await chooser.setFiles(uploadPath);
}

async function addPetAndPost(page) {
  await waitForText(page, 'Who are we meeting?');
  await shot(page, '390-pet-setup.png');
