const assert = require('node:assert/strict');
const fs = require('node:fs');
const Module = require('node:module');
const path = require('node:path');
const ts = require('typescript');

const root = path.resolve(__dirname, '..');
const databaseFile = path.join(root, 'src/storage/pet-database.web.ts');
const originalLoad = Module._load;

require.extensions['.ts'] = (mod, filename) => {
  const source = fs.readFileSync(filename, 'utf8');
  mod._compile(
    ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText,
    filename
  );
};

Module._load = function (request, parent, isMain) {
  if (request === 'expo-sqlite' || request === 'expo-file-system') {
    throw new Error(`The web data test loaded ${request}.`);
  }
  return originalLoad.call(this, request, parent, isMain);
};

function installSessionStorage(methods = {}) {
  const backing = new Map();
  const storage = {
    getItem(key) {
      if (methods.getItem) {
        return methods.getItem(key);
      }
      return backing.has(key) ? backing.get(key) : null;
    },
    setItem(key, value) {
      if (methods.setItem) {
        methods.setItem(key, value);
        return;
      }
      backing.set(key, String(value));
    },
    removeItem(key) {
      if (methods.removeItem) {
        methods.removeItem(key);
        return;
      }
      backing.delete(key);
    },
  };
  globalThis.sessionStorage = storage;
  return backing;
}

function loadDatabase() {
  delete require.cache[databaseFile];
  return require(databaseFile);
}

function ids(items) {
  return items.map((item) => item.id).sort();
}

async function main() {
  const seed = require(path.join(root, 'src/data/pet-seed.ts'));
  const seedPetIds = ids(seed.INITIAL_SEEDED_PETS);
  const seedPostIds = ids(seed.INITIAL_SEEDED_POSTS);
  assert.ok(seedPetIds.length >= 6);
  assert.ok(seedPostIds.length >= 8);

  installSessionStorage();
  let api = loadDatabase();
  let snapshot = await api.getPetSnapshot();
  assert.deepEqual(ids(snapshot.pets), seedPetIds);
  assert.deepEqual(ids(snapshot.posts), seedPostIds);
  assert.deepEqual(snapshot.reactions, {});

  const pet = await api.saveLocalPetProfile({
    name: 'Biscuit',
    species: 'Dog',
    photoUri: 'data:image/gif;base64,R0lGODlhAQABAAAAACw=',
    personality: 'Soft ears.',
  });
  const post = await api.createLocalPetPost({
    petId: pet.id,
    photoUri: pet.photoUri,
    caption: 'Biscuit found a sunbeam.',
  });
  snapshot = await api.getPetSnapshot();
  assert.ok(snapshot.pets.some((item) => item.id === pet.id && item.name === 'Biscuit'));
  assert.ok(snapshot.posts.some((item) => item.id === post.id && item.caption === post.caption));

  api = loadDatabase();
  snapshot = await api.getPetSnapshot();
  assert.ok(snapshot.pets.some((item) => item.id === pet.id));
  assert.ok(snapshot.posts.some((item) => item.id === post.id));

  await api.resetPetDatabase();
  snapshot = await api.getPetSnapshot();
  assert.deepEqual(ids(snapshot.pets), seedPetIds);
  assert.deepEqual(ids(snapshot.posts), seedPostIds);
  assert.equal(
    snapshot.pets.some((item) => item.id === pet.id),
    false
  );

  installSessionStorage({
    getItem() {
      throw new Error('sessionStorage is blocked');
    },
    setItem() {
      throw new Error('sessionStorage is blocked');
    },
    removeItem() {
      throw new Error('sessionStorage is blocked');
    },
  });
  api = loadDatabase();
  snapshot = await api.getPetSnapshot();
  assert.deepEqual(ids(snapshot.pets), seedPetIds);
  const blockedPet = await api.saveLocalPetProfile({
    name: 'Pebble',
    species: 'Cat',
    photoUri: 'asset:Tippy.jpeg',
    personality: 'Quiet.',
  });
  const blockedPost = await api.createLocalPetPost({
    petId: blockedPet.id,
    photoUri: 'asset:Tippy.jpeg',
    caption: 'Pebble stayed in memory.',
  });
  snapshot = await api.getPetSnapshot();
  assert.ok(snapshot.pets.some((item) => item.id === blockedPet.id));
  assert.ok(snapshot.posts.some((item) => item.id === blockedPost.id));
  await api.resetPetDatabase();
  snapshot = await api.getPetSnapshot();
  assert.deepEqual(ids(snapshot.pets), seedPetIds);
  assert.equal(
    snapshot.posts.some((item) => item.id === blockedPost.id),
    false
  );

  api = loadDatabase();
  snapshot = await api.getPetSnapshot();
  assert.equal(
    snapshot.pets.some((item) => item.name === 'Pebble'),
    false
  );
  assert.deepEqual(ids(snapshot.pets), seedPetIds);

  console.log('web pet data: seed, create, reset, and storage fallback passed');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

import type { ReactNode } from 'react';
import { useEffect, useMemo } from 'react';
import { DarkTheme, DefaultTheme, Stack, ThemeProvider } from 'expo-router';
import { useFonts } from 'expo-font';
import { Platform, StatusBar } from 'react-native';
import { NavigationBar } from 'expo-navigation-bar';
import * as SystemUI from 'expo-system-ui';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { KeyboardProvider } from 'react-native-keyboard-controller';
import { SafeAreaProvider } from 'react-native-safe-area-context';

import themeFontAssets from '../theme/font-assets';
import { AppThemeProvider, useAppTheme } from '../theme/provider';

function RouterThemeBridge({ children }: { children: ReactNode }) {
  const theme = useAppTheme();
  const prefersDark = theme.activeScheme === 'dark';
  const base = prefersDark ? DarkTheme : DefaultTheme;
  const shellColor = theme.activeColors.background;
  const routerTheme = useMemo(
    () => ({
      ...base,
      colors: {
        ...base.colors,
        background: shellColor,
        border: theme.activeColors.surface,
        card: shellColor,
        notification: theme.activeColors.warning,
        primary: theme.activeColors.primary,
        text: theme.activeColors.text,
      },
    }),
    [base, shellColor, theme.activeColors]
  );

  useEffect(() => {
    void SystemUI.setBackgroundColorAsync?.(shellColor);
  }, [shellColor]);

  return <ThemeProvider value={routerTheme}>{children}</ThemeProvider>;
}

function LayoutInner() {
  const theme = useAppTheme();
  const shellColor = theme.activeColors.background;

  return (
    <GestureHandlerRootView style={{ flex: 1, backgroundColor: shellColor }}>
      <KeyboardProvider>
        <SafeAreaProvider>
          <RouterThemeBridge>
            <StatusBar
              barStyle={theme.activeScheme === 'dark' ? 'light-content' : 'dark-content'}
            />
            {Platform.OS === 'android' ? (
              <NavigationBar style={theme.activeScheme === 'dark' ? 'dark' : 'light'} />
            ) : null}
            <Stack
              screenOptions={{
                contentStyle: { backgroundColor: shellColor },
                headerBackButtonDisplayMode: 'minimal',
                headerShadowVisible: false,
                headerStyle: { backgroundColor: shellColor },
                headerTintColor: theme.activeColors.primary,
                headerTitleStyle: { color: theme.activeColors.text, fontWeight: '700' },
              }}>
              <Stack.Screen name="index" options={{ headerShown: false }} />
              <Stack.Screen name="onboarding" options={{ headerShown: false }} />
              <Stack.Screen name="onboarding/features" options={{ title: 'Your first visit' }} />
              <Stack.Screen name="onboarding/complete" options={{ title: 'All set' }} />
              <Stack.Screen name="pet-setup" options={{ title: 'Pet profile' }} />
              <Stack.Screen name="create-post" options={{ title: 'Share a photo' }} />
              <Stack.Screen name="my-pet" options={{ title: 'My pet' }} />
              <Stack.Screen name="post/[id]" options={{ title: 'Pet moment' }} />
              <Stack.Screen
                name="settings"
                options={{ presentation: 'modal', title: 'Settings' }}
              />
              <Stack.Screen name="exposition/index" options={{ title: 'Package Exposition' }} />
              <Stack.Screen name="exposition/stylist" options={{ title: 'Stylist' }} />
              <Stack.Screen name="exposition/data" options={{ title: 'Data' }} />
              <Stack.Screen name="exposition/sdk-56" options={{ title: 'Expo SDK' }} />
            </Stack>
          </RouterThemeBridge>
        </SafeAreaProvider>
      </KeyboardProvider>
    </GestureHandlerRootView>
  );
}

export default function Layout() {
  const hasFontAssets = Object.keys(themeFontAssets).length > 0;
  const [fontsLoaded, fontsError] = useFonts(themeFontAssets);

  if (hasFontAssets && !fontsLoaded && !fontsError) {
    return null;
  }

  return (
    <AppThemeProvider>
      <LayoutInner />
    </AppThemeProvider>
  );
}

