import { useCallback, useEffect, useState } from 'react';

import { createMemoryOnboardingStateAdapter } from './onboarding-state-memory';
import type { OnboardingState, OnboardingStateAdapter } from './onboarding-state-types';

let onboardingStateAdapter: OnboardingStateAdapter = createMemoryOnboardingStateAdapter();
type OnboardingStateListener = (state?: OnboardingState) => void;

const onboardingStateListeners = new Set<OnboardingStateListener>();
let currentOnboardingUserId: string | undefined;

function notifyOnboardingStateChanged(state?: OnboardingState): void {
  for (const listener of onboardingStateListeners) {
    listener(state);
  }
}

export function configureOnboardingStateAdapter(adapter: OnboardingStateAdapter): void {
  onboardingStateAdapter = adapter;
  notifyOnboardingStateChanged();
}

export function getOnboardingStateAdapter(): OnboardingStateAdapter {
  return onboardingStateAdapter;
}

export function setOnboardingStateUserId(userId?: string | null): void {
  currentOnboardingUserId = userId ?? undefined;
}

export function subscribeToOnboardingStateChanges(listener: OnboardingStateListener): () => void {
  onboardingStateListeners.add(listener);
  return () => {
    onboardingStateListeners.delete(listener);
  };
}

export async function markOnboardingComplete(input?: {
  userId?: string;
  completedAt?: string;
}): Promise<OnboardingState> {
  const next = await onboardingStateAdapter.markComplete({
    ...input,
    userId: input?.userId ?? currentOnboardingUserId,
  });
  notifyOnboardingStateChanged(next);
  return next;
}

export function useOnboardingState(userId?: string) {
  const adapter = onboardingStateAdapter;
  const [state, setState] = useState<OnboardingState | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | undefined>();

  const refresh = useCallback(async () => {
    setIsLoading(true);
    setError(undefined);
    try {
      const next = await adapter.loadState(userId);
      setState(next);
      return next;
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : 'Unable to load onboarding state.';
      setError(message);
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [adapter, userId]);

  useEffect(() => {
    const timer = setTimeout(() => {
      void refresh();
    }, 0);
    return () => clearTimeout(timer);
  }, [refresh]);

  useEffect(
    () =>
      subscribeToOnboardingStateChanges((nextState) => {
        if (nextState) {
          setState(nextState);
          setError(undefined);
          setIsLoading(false);
          return;
        }
        void refresh();
      }),
    [refresh]
  );

  return {
    adapter,
    state,
    isLoading,
    error,
    refresh,
    markComplete: async (input?: { completedAt?: string }) => {
      const next = await adapter.markComplete({ userId, completedAt: input?.completedAt });
      setState(next);
      setError(undefined);
      setIsLoading(false);
      notifyOnboardingStateChanged(next);
      return next;
    },
  };
}

import {
  createEmptyOnboardingState,
  upsertLegalAcceptance,
  type OnboardingDocumentAcceptance,
  type OnboardingState,
  type OnboardingStateAdapter,
} from './onboarding-state-types';

export type MemoryLegalDocument = {
  documentId: OnboardingDocumentAcceptance['documentId'];
  acceptanceVersion: string;
};

export type MemoryLegalSnapshot = {
  status: 'needs-legal' | 'complete';
  requiredDocuments: MemoryLegalDocument[];
  acceptedDocumentKeys: string[];
};

export type MemoryLegalAcceptanceAdapter = {
  loadRequiredLegalAcceptances(
    requiredDocuments: MemoryLegalDocument[],
    userId?: string
  ): Promise<MemoryLegalSnapshot>;
  acceptLegalDocument(
    document: MemoryLegalDocument,
    input?: { userId?: string; flowId?: string; flowVersion?: number }
  ): Promise<void>;
};

type MemoryStore = {
  state: OnboardingState | null;
};

export function createMemoryOnboardingStore(initial?: OnboardingState | null): MemoryStore {
  return { state: initial ?? null };
}

export function createMemoryOnboardingStateAdapter(
  store: MemoryStore = createMemoryOnboardingStore()
): OnboardingStateAdapter {
  return {
    mode: 'memory',
    async loadState() {
      return store.state
        ? { ...store.state, legalAcceptances: [...store.state.legalAcceptances] }
        : null;
    },
    async saveState(state: OnboardingState) {
      store.state = {
        ...state,
        legalAcceptances: [...state.legalAcceptances],
      };
    },
    async markComplete(input) {
      const current = store.state ?? createEmptyOnboardingState();
      const next = {
        ...current,
        completedAt: input?.completedAt ?? new Date().toISOString(),
        currentStep: 'complete',
      };
      store.state = next;
      return next;
    },
  };
}

export function createMemoryLegalAcceptanceAdapter(
  store: MemoryStore = createMemoryOnboardingStore()
): MemoryLegalAcceptanceAdapter {
  return {
    async loadRequiredLegalAcceptances(requiredDocuments: MemoryLegalDocument[]) {
      const acceptedDocumentKeys = (store.state?.legalAcceptances ?? []).map(
        (item) => `${item.documentId}@${item.documentVersion}`
      );
      const accepted = new Set(acceptedDocumentKeys);
      const missingDocuments = requiredDocuments.filter(
        (document) => !accepted.has(`${document.documentId}@${document.acceptanceVersion}`)
      );

      return {
        status: missingDocuments.length > 0 ? 'needs-legal' : 'complete',
        requiredDocuments: missingDocuments,
        acceptedDocumentKeys,
      };
    },

    async acceptLegalDocument(document, input) {
      const current = store.state ?? createEmptyOnboardingState();
      store.state = upsertLegalAcceptance(current, {
        documentId: document.documentId,
        documentVersion: document.acceptanceVersion,
        acceptedAt: new Date().toISOString(),
        userId: input?.userId,
        flowId: input?.flowId,
        flowVersion: input?.flowVersion,
      });
    },
  };
}

export function createMemoryOnboardingPersistence(
  store: MemoryStore = createMemoryOnboardingStore()
) {
  return {
    store,
    onboarding: createMemoryOnboardingStateAdapter(store),
    legal: createMemoryLegalAcceptanceAdapter(store),
  };
}

export type OnboardingPersistenceMode =
  'memory' | 'zustand-local' | 'supabase' | 'zustand-supabase';

export const DEFAULT_ONBOARDING_FLOW_ID = 'mds/onboarding';
export const DEFAULT_ONBOARDING_FLOW_VERSION = 1;

export type OnboardingDocumentAcceptance = {
  documentId: 'terms' | 'privacy';
  documentVersion: string;
  acceptedAt: string;
  userId?: string;
  flowId?: string;
  flowVersion?: number;
};

export type OnboardingState = {
  flowId: string;
  flowVersion: number;
  currentStep?: string;
  completedAt?: string;
  legalAcceptances: OnboardingDocumentAcceptance[];
  pendingSync?: boolean;
};

export type OnboardingStateAdapter = {
  mode: OnboardingPersistenceMode;
  loadState(userId?: string): Promise<OnboardingState | null>;
  saveState(state: OnboardingState, userId?: string): Promise<void>;
  markComplete(input?: { userId?: string; completedAt?: string }): Promise<OnboardingState>;
  syncPending?(userId: string): Promise<OnboardingState>;
};

export function createEmptyOnboardingState(input: Partial<OnboardingState> = {}): OnboardingState {
  return {
    flowId: input.flowId ?? DEFAULT_ONBOARDING_FLOW_ID,
    flowVersion: input.flowVersion ?? DEFAULT_ONBOARDING_FLOW_VERSION,
    currentStep: input.currentStep,
    completedAt: input.completedAt,
    legalAcceptances: input.legalAcceptances ?? [],
    pendingSync: input.pendingSync,
  };
}

export function upsertLegalAcceptance(
  state: OnboardingState,
  acceptance: OnboardingDocumentAcceptance
): OnboardingState {
  const remaining = state.legalAcceptances.filter(
    (item) =>
      !(
        item.documentId === acceptance.documentId &&
        item.documentVersion === acceptance.documentVersion
      )
  );
  return {
    ...state,
    legalAcceptances: [...remaining, acceptance],
  };
}

