export async function saveLocalReaction(postId: string, reaction: ReactionKind | null) {
  await initializePetDatabase();
  const database = await getDatabase();
  if (!reaction) {
    await database.runAsync('DELETE FROM reactions WHERE postId = ?', postId);
    return;
  }

  await database.runAsync(
    'INSERT INTO reactions (postId, value) VALUES (?, ?) ' +
      'ON CONFLICT(postId) DO UPDATE SET value = excluded.value',
    postId,
    reaction
  );
}

import { INITIAL_SEEDED_PETS, INITIAL_SEEDED_POSTS } from '../data/pet-seed';
import type {
  Pet,
  PetPost,
  PetPostInput,
  PetProfileInput,
  PetSnapshot,
  ReactionKind,
} from '../types/pet';

const SESSION_KEY = 'pet-show-and-tell.preview.v1';

interface MemoryState {
  pets: Pet[];
  posts: PetPost[];
  reactions: Record<string, ReactionKind>;
}

let state: MemoryState | undefined;

function cloneSeed(): MemoryState {
  return {
    pets: INITIAL_SEEDED_PETS.map((pet) => ({ ...pet })),
    posts: INITIAL_SEEDED_POSTS.map((post) => ({ ...post })),
    reactions: {},
  };
}

function isReaction(value: unknown): value is ReactionKind {
  return value === 'like' || value === 'love';
}

function readSession(): MemoryState | undefined {
  try {
    if (typeof sessionStorage === 'undefined') {
      return undefined;
    }
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (!raw) {
      return undefined;
    }
    const parsed = JSON.parse(raw) as Partial<MemoryState>;
    if (!parsed || !Array.isArray(parsed.pets) || !Array.isArray(parsed.posts)) {
      return undefined;
    }
    const reactions: Record<string, ReactionKind> = {};
    if (parsed.reactions && typeof parsed.reactions === 'object') {
      for (const [postId, value] of Object.entries(parsed.reactions)) {
        if (isReaction(value)) {
          reactions[postId] = value;
        }
      }
    }
    return {
      pets: parsed.pets.map((pet) => ({ ...pet })),
      posts: parsed.posts.map((post) => ({ ...post })),
      reactions,
    };
  } catch {
    return undefined;
  }
}

function clearSession() {
  try {
    if (typeof sessionStorage === 'undefined') {
      return;
    }
    sessionStorage.removeItem(SESSION_KEY);
  } catch {
    // The tab keeps the in-memory snapshot when storage is blocked.
  }
}

function writeSession(next: MemoryState) {
  try {
    if (typeof sessionStorage === 'undefined') {
      return;
    }
    sessionStorage.setItem(SESSION_KEY, JSON.stringify(next));
  } catch {
    clearSession();
  }
}

function snapshotOf(next: MemoryState): PetSnapshot {
  return {
    pets: next.pets.map((pet) => ({ ...pet })),
    posts: next.posts
      .map((post) => ({ ...post }))
      .sort((left, right) => right.createdAt.localeCompare(left.createdAt)),
    reactions: { ...next.reactions },
  };
}

function locationRequestsReset() {
  try {
    if (typeof window === 'undefined') {
      return false;
    }
    return new URLSearchParams(window.location.search).get('reset') === '1';
  } catch {
    return false;
  }
}

export function createLocalId(prefix: string) {
  return prefix + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
}

export async function initializePetDatabase() {
  if (state) {
    return;
  }
  if (locationRequestsReset()) {
    clearSession();
    state = cloneSeed();
    return;
  }
  state = readSession() ?? cloneSeed();
}

export async function getPetSnapshot(): Promise<PetSnapshot> {
  await initializePetDatabase();
  return snapshotOf(state as MemoryState);
}

export async function saveLocalPetProfile(input: PetProfileInput, petId?: string): Promise<Pet> {
  await initializePetDatabase();
  const current = state as MemoryState;

  if (petId) {
    const index = current.pets.findIndex((pet) => pet.id === petId && pet.isUserPet);
    if (index < 0) {
      throw new Error('This pet profile could not be found.');
    }
    const updated: Pet = {
      ...current.pets[index],
      name: input.name.trim(),
      species: input.species.trim(),
      photoUri: input.photoUri,
      personality: input.personality.trim(),
    };
    current.pets[index] = updated;
    writeSession(current);
    return { ...updated };
  }

  const pet: Pet = {
    id: createLocalId('pet-user'),
    name: input.name.trim(),
    species: input.species.trim(),
    photoUri: input.photoUri,
    personality: input.personality.trim(),
    createdAt: new Date().toISOString(),
    isUserPet: true,
  };
  current.pets.push(pet);
  writeSession(current);
  return { ...pet };
}

export async function createLocalPetPost(input: PetPostInput): Promise<PetPost> {
  await initializePetDatabase();
  const current = state as MemoryState;
  const post: PetPost = {
    id: createLocalId('post-local'),
    petId: input.petId,
    photoUri: input.photoUri,
    caption: input.caption.trim(),
    createdAt: new Date().toISOString(),
  };
  current.posts.push(post);
  writeSession(current);
  return { ...post };
}

export async function saveLocalReaction(postId: string, reaction: ReactionKind | null) {
  await initializePetDatabase();
  const current = state as MemoryState;
  if (!reaction) {
    delete current.reactions[postId];
  } else {
    current.reactions[postId] = reaction;
  }
  writeSession(current);
}

export async function resetPetDatabase() {
  clearSession();
  state = cloneSeed();
}

export async function consumeWebPreviewReset() {
  if (!locationRequestsReset()) {
    return false;
  }
  await resetPetDatabase();
  return true;
}

function parseHexColor(color: string): [number, number, number] | null {
  const normalized = color.trim().replace(/^#/, '');

  if (/^[0-9a-f]{3}$/i.test(normalized)) {
    return normalized.split('').map((value) => parseInt(`${value}${value}`, 16)) as [
      number,
      number,
      number,
    ];
  }

  if (/^[0-9a-f]{6}$/i.test(normalized)) {
    return [
      parseInt(normalized.slice(0, 2), 16),
      parseInt(normalized.slice(2, 4), 16),
      parseInt(normalized.slice(4, 6), 16),
    ];
  }

  return null;
}

function toLinearChannel(value: number): number {
  const channel = value / 255;
  return channel <= 0.03928 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
}

export function getReadableTextColor(
  backgroundColor: string,
  darkText = '#111827',
  lightText = '#ffffff'
): string {
  const rgb = parseHexColor(backgroundColor);
  if (!rgb) {
    return lightText;
  }

  const [red, green, blue] = rgb.map(toLinearChannel);
  const luminance = 0.2126 * red + 0.7152 * green + 0.0722 * blue;

  return luminance > 0.45 ? darkText : lightText;
}

import {
  createContext,
  useContext,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react';
import { Appearance, useColorScheme } from 'react-native';

import defaultThemeTokens, {
  type StylistColorPalette,
  type StylistColorScheme,
  type StylistThemeTokens,
} from './tokens';

export type AppThemeValue = StylistThemeTokens & {
  activeScheme: StylistColorScheme;
  activeColors: StylistColorPalette;
};

type AppThemeSchemePreference = StylistColorScheme | 'preview' | 'system';
export type AppThemeColorOverrides = Partial<
  Record<StylistColorScheme, Partial<StylistColorPalette>>
>;

export function readSystemScheme(): StylistColorScheme | null {
  const scheme = Appearance.getColorScheme();
  return scheme === 'light' || scheme === 'dark' ? scheme : null;
}

const initialSystemScheme = readSystemScheme() ?? 'light';

const AppThemeContext = createContext<AppThemeValue>({
  ...defaultThemeTokens,
  activeScheme: initialSystemScheme,
  activeColors: defaultThemeTokens.colors[initialSystemScheme],
});
const AppThemeSetterContext = createContext<Dispatch<SetStateAction<StylistThemeTokens>> | null>(
  null
);

function resolveActiveScheme(
  theme: StylistThemeTokens,
  systemScheme: ReturnType<typeof useColorScheme>,
  preference: AppThemeSchemePreference
): StylistColorScheme {
  if (preference === 'light' || preference === 'dark') {
    return preference;
  }
  if (preference === 'preview') {
    return theme.colorSystem.previewScheme;
  }
  if (systemScheme === 'light' || systemScheme === 'dark') {
    return systemScheme;
  }
  return readSystemScheme() ?? 'light';
}

export function AppThemeProvider({
  children,
  colors,
  scheme = 'system',
}: {
  children: ReactNode;
  colors?: AppThemeColorOverrides;
  scheme?: AppThemeSchemePreference;
}) {
  const [theme, setTheme] = useState<StylistThemeTokens>(defaultThemeTokens);
  const systemScheme = useColorScheme();
  const value = useMemo<AppThemeValue>(() => {
    const activeScheme = resolveActiveScheme(theme, systemScheme, scheme);
    const mergedColors = {
      light: { ...theme.colors.light, ...colors?.light },
      dark: { ...theme.colors.dark, ...colors?.dark },
    };

    return {
      ...theme,
      colors: mergedColors,
      activeScheme,
      activeColors: mergedColors[activeScheme],
    };
  }, [colors, scheme, systemScheme, theme]);

  return (
    <AppThemeSetterContext.Provider value={setTheme}>
      <AppThemeContext.Provider value={value}>{children}</AppThemeContext.Provider>
    </AppThemeSetterContext.Provider>
  );
}

export function useAppTheme() {
  return useContext(AppThemeContext);
}

export function useSetAppTheme() {
  const setTheme = useContext(AppThemeSetterContext);
  if (!setTheme) {
    throw new Error('useSetAppTheme must be used inside AppThemeProvider.');
  }
  return setTheme;
}

export type StylistColorScheme = 'light' | 'dark';
export type StylistColorMode = 'bg' | 'automatic';
export type StylistFamilyMode = 'one' | 'two';

export interface StylistColorPalette {
  background: string;
  surface: string;
  text: string;
  primary: string;
  secondary: string;
  success: string;
  warning: string;
}

export interface StylistSemanticFamilies {
  primary: string;
  secondary: string;
  success: string;
  warning: string;
}

export interface StylistThemeTokens {
  version: 1;
  colorSystem: {
    mode: StylistColorMode;
    previewScheme: StylistColorScheme;
    familyMode: StylistFamilyMode;
  };
  families: {
    light: StylistSemanticFamilies;
    dark: StylistSemanticFamilies;
  };
  palettes: {
    bg: {
      light: StylistColorPalette;
      dark: StylistColorPalette;
    };
    automatic: {
      light: StylistColorPalette;
      dark: StylistColorPalette;
    };
  };
  colors: {
    light: StylistColorPalette;
    dark: StylistColorPalette;
  };
  typography: {
    fontFamily: string;
    fontDisplay: string;
    fontTitle: string;
    fontSubtitle: string;
    fontBody: string;
    fontCaption: string;
    fontMono: string;
    displaySize: number;
    headingSize: number;
    bodySize: number;
    captionSize: number;
  };
  layout: {
    radius: number;
    spacing: {
      xs: number;
      sm: number;
      md: number;
      lg: number;
      xl: number;
    };
  };
}

